"""``workpeg project create`` — scaffold a whole peg: UI, function, manifest.

A peg is TWO halves and a document that binds them. Until now the SDK
scaffolded each half separately (``workpeg function new``, ``workpeg ui new``)
and left the manifest to be written by hand, which meant the common case —
"I am building a peg" — was three commands and a file nobody had a template
for.

WHY ONE FOLDER WITH TWO SUBDIRECTORIES

    my-peg/
      workpeg.json     the manifest: namespace, target SDK, function
                       entrypoint, runtime
      AGENTS.md        the guide a coding agent reads first (CLAUDE.md
      CLAUDE.md        imports it)
      ui/              workpeg ui serve|build          point here
      function/        workpeg function run|build      point here

The halves sit in subdirectories rather than merged at the root because each
existing command already expects to own its directory: ``workpeg ui build``
wants ``main.py`` at the path it is given, and the function commands want a
``Dockerfile`` at theirs. Merging them would mean teaching every command a new
layout; separating them means every command keeps working and only learns a
path.

The manifest sits at the root because it describes the PEG, not either half —
and because ``workpeg project submit`` reads it to send both together.
"""
from __future__ import annotations

import re
from importlib import resources
from pathlib import Path

from workpeg import function_base, target_sdk
from workpeg.starter import (
    PLACEHOLDER, TemplateExists, copy_template, write_agent_guide,
    write_starter,
)

__all__ = ["PLACEHOLDER", "ProjectError", "create_project",
           "validate_namespace"]

#: What a namespace may be. It becomes the first label of
#: <namespace>.workpeg.com, so it is bounded by DNS, not by taste — and by the
#: platform's standing reservation of the "pv-" prefix.
_VALID = re.compile(r"^[a-z][a-z0-9-]{1,61}[a-z0-9]$")

#: Reserved because they name an environment or a service rather than a peg,
#: and a peg holding one would shadow it.
RESERVED = {
    "www", "api", "cdn", "app", "admin", "accounts", "support", "docs",
    "dev", "staging", "preview", "repo", "mail", "smtp", "mx", "space",
}


#: Prefixes the platform keeps: ``pv-`` for private previews, ``dv-`` for a
#: dev install's own test space (``dv-<uuid>``).
RESERVED_PREFIXES = ("pv-", "dv-")


class ProjectError(Exception):
    """The scaffold cannot be created. The message is for the developer."""


def validate_namespace(name: str) -> str:
    """Check *name* can actually be a peg, or explain why not.

    Checked HERE rather than at submit time, because the namespace becomes a
    directory, a manifest field and eventually a hostname — and finding out at
    the end that the name was never usable means redoing all three.
    """
    value = (name or "").strip().lower()
    if not value:
        raise ProjectError("A peg needs a name.")
    for prefix in RESERVED_PREFIXES:
        if value.startswith(prefix):
            raise ProjectError(
                f"'{value}' starts with '{prefix}', which Workpeg reserves. "
                f"Pick another name.")
    if value in RESERVED:
        raise ProjectError(
            f"'{value}' is reserved — it names a Workpeg service rather than "
            f"a peg.")
    if not _VALID.match(value):
        raise ProjectError(
            f"'{value}' cannot be a hostname label. Use lowercase letters, "
            f"digits and hyphens; start with a letter, end with a letter or "
            f"digit, 3-63 characters.")
    return value


def create_project(target: Path, namespace: str, *, force: bool = False):
    """Write the scaffold into *target*. Returns the created path.

    The manifest and the function come from ``templates/project/``; ``ui/``
    is the same Scaffold starter ``workpeg ui new`` writes; ``AGENTS.md`` and
    ``CLAUDE.md`` go at the root, where an agent working in either half finds
    them, and an existing one is kept even under *force*.
    """
    namespace = validate_namespace(namespace)
    target = Path(target).expanduser().resolve()

    if target.exists() and any(target.iterdir()) and not force:
        raise ProjectError(
            f"{target} already exists and is not empty. Use --force to write "
            f"into it anyway.")

    # Named before anything is written, so an SDK that cannot name the
    # function's base image leaves no half-made peg behind.
    try:
        base_version = function_base.base_version()
    except function_base.BaseVersionError as exc:
        raise ProjectError(str(exc)) from None

    source = resources.files("workpeg") / "templates" / "project"
    with resources.as_file(source) as root:
        _copy(Path(root), target, namespace, force=force)
    for filled in ("Dockerfile", "wheels/README.txt"):
        path = target / "function" / filled
        path.write_text(
            function_base.fill(path.read_text(encoding="utf-8"),
                               base_version), encoding="utf-8")
    # The SDK Workpeg will build this peg with: the one installed here, the
    # version the function's base was just named from (target_sdk).
    manifest = target / target_sdk.MANIFEST
    manifest.write_text(
        target_sdk.fill(manifest.read_text(encoding="utf-8"), base_version),
        encoding="utf-8")
    try:
        write_starter(target / "ui", namespace, force=force)
    except TemplateExists as exc:
        raise ProjectError(str(exc)) from None
    write_agent_guide(target, namespace)
    return target


def _copy(source: Path, target: Path, namespace: str, *, force: bool):
    try:
        copy_template(source, target, namespace, force=force)
    except TemplateExists as exc:
        raise ProjectError(str(exc)) from None
